WITH flattened AS (SELECT id, effective_from, element FROM price_tiers LATERAL VIEW OUTER EXPLODE(discounts) t AS element) SELECT DATE_TRUNC('WEEK', effective_from) AS week_start, DATE_TRUNC('YEAR', effective_from) AS year_start, APPROX_PERCENTILE(element, ARRAY(0.25, 0.5, 0.75)) AS element_quartiles, COUNT(*) AS num_rows, PERCENTILE_APPROX(element, 0.5) AS element_p50, COUNT(*) AS row_count, COUNT(DISTINCT id) AS distinct_ids FROM flattened GROUP BY GROUPING SETS ((DATE_TRUNC('WEEK', effective_from), DATE_TRUNC('YEAR', effective_from)), (DATE_TRUNC('WEEK', effective_from)))
